-- Read-only current matching snapshot, not a historical insertion-time diagnosis.
-- Derived from queue_listing_delivery_v3 on 2026-09-08; keep aligned when that function changes.
select l.source_id,count(*) active,count(*) filter(where fresh_delivery_eligible) fresh,count(*) filter(where matches>0) profile_match,count(*) filter(where matches>0 and fresh_delivery_eligible and is_primary_listing and quality_status<>'rejected' and enrichment_delivery_eligible) match_and_eligible,count(*) filter(where matches>0 and fresh_delivery_eligible and is_primary_listing and quality_status<>'rejected' and enrichment_delivery_eligible and not exists(select 1 from delivery_events d where d.listing_id=l.id)) eligible_without_event from listings l cross join lateral(select count(*) matches from public.search_profiles p join public.bot_users owner_user on owner_user.id=p.user_id and owner_user.is_active=true
 where p.is_active=true and (p.profile_slot=1 or app_private.user_is_premium(p.user_id))
 and (coalesce(cardinality(p.property_types),0)=0 or (lower(concat_ws(' ',l.property_type,l.title,l.district,l.address,l.raw::text)) ~ '(tauschwohnung|tauschangebot|wohnungstausch|wohnung[[:space:]-]*tausch|tausche)' and 'Tauschwohnung'=any(p.property_types)) or (lower(concat_ws(' ',l.property_type,l.title,l.district,l.address,l.raw::text)) !~ '(tauschwohnung|tauschangebot|wohnungstausch|wohnung[[:space:]-]*tausch|tausche)' and coalesce(l.property_type,'Wohnung')=any(p.property_types)))
 and (p.max_warm_rent is null or (coalesce(nullif(l.warm_rent,0),nullif(l.cold_rent,0)) is not null and coalesce(nullif(l.warm_rent,0),nullif(l.cold_rent,0))<=p.max_warm_rent)) and (not p.require_known_warm_rent or coalesce(l.warm_rent,0)>0)
 and (p.max_deposit is null or l.deposit is null or l.deposit<=p.max_deposit) and (not p.wbs_only or l.wbs_required is true) and (p.furnished_preference='any' or (p.furnished_preference='yes' and l.furnished is true) or (p.furnished_preference='no' and l.furnished is false))
 and (coalesce(p.min_rooms,0)<=0 or l.rooms is null or l.rooms>=p.min_rooms) and (coalesce(p.min_area_sqm,0)<=0 or l.area_sqm is null or l.area_sqm>=p.min_area_sqm)
 and (p.location_mode='all_hamburg' or (p.location_mode='boroughs' and coalesce(cardinality(p.boroughs),0)>=7) or (p.location_mode='neighborhoods' and exists(select 1 from unnest(p.neighborhoods) n where lower(concat_ws(' ',l.district,l.address,l.title,l.raw::text)) like '%'||lower(n)||'%')) or (p.location_mode='boroughs' and exists(select 1 from public.hamburg_neighborhoods hn join public.hamburg_boroughs hb on hb.id=hn.borough_id where hb.name=any(p.boroughs) and lower(concat_ws(' ',l.district,l.address,l.title,l.raw::text)) like '%'||lower(hn.name)||'%')) or (coalesce(cardinality(p.districts),0)>0 and ('Ganz Hamburg'=any(p.districts) or exists(select 1 from unnest(p.districts) d where lower(concat_ws(' ',l.district,l.address,l.title,l.raw::text)) like '%'||lower(d)||'%'))))
 )m where l.is_active group by l.source_id order by l.source_id;

SELECT s.id,s.name,r.started_at,r.success,r.fetched_count,r.inserted_count,r.error_message,r.metadata
FROM public.sources s LEFT JOIN LATERAL (SELECT * FROM public.crawl_runs WHERE source_id=s.id ORDER BY started_at DESC LIMIT 1)r ON true ORDER BY s.id;

